INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ausathdzil/lounge/gh-cli', 'gh-cli', 'ausathdzil', 'lounge', 'community', 'gh-cli ausathdzil lounge community GitHub CLI（gh）是GitHub的命令行工具，帮助开发者高效工作 GitHub CLI（gh）は、開発者が効率的に作業できるGitHubのコマンドラインツールです GitHub CLI(gh)는 개발자가 효율적으로 작업할 수 있는 GitHub의 명령줄 도구입니다 gh-cli es una herramienta de línea de comandos para GitHub que permite trabajar de forma eficiente con el servicio. gh-cli est un outil de ligne de commande pour GitHub qui permet de travailler de manière efficace avec le service. gh-cli ist ein Kommandozeilen-Tool für GitHub, das eine effiziente Arbeit mit dem Dienst ermöglicht. O GitHub CLI é uma ferramenta de linha de comando que permite trabalhar de forma eficiente com o GitHub. Saiba mais sobre como instalá-lo e usá-lo. GitHub CLI — это инструмент командной строки, который позволяет эффективно работать с GitHub. Узнайте больше о том, как его устанавливать и использовать. GitHub CLI هي أداة سطر الأوامر التي تمكنك من العمل بفعالية مع GitHub. تعرف على المزيد حول كيفية تثبيتها واستخدامها. A personal movie tracker GNOME app GitHub CLI gh 命令行工具 开发效率 版本管理 代码审查 GitHub集成 A personal movie tracker GNOME app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jtdowney/dotfiles/search-operations', 'community', 'jtdowney', 'dotfiles', 'jtdowney/dotfiles', 'search-operations', 0, 0, 70, '2026-02-20T04:13:19.572Z', '2026-02-20T04:27:03.345Z', '83e8e1ee45541dcf57b2a539e315744529edd3b9ac4cd8f37442297f1cd0f02c', '{"id":"jtdowney/dotfiles/search-operations","name":"search-operations","description":{"zh":"GitHub 搜索操作技能提供了全面的搜索功能，包括代码、问题、拉取请求、仓库和用户搜索","ja":"GitHub 検索操作スキルは、コード、問題、プルリクエスト、リポジトリ、ユーザーの包括的な検索機能を提供","ko":"GitHub 검색 연산 스킬은 코드, 문제, 풀 리퀘스트, 저장소 및 사용자의 포괄적인 검색 기능을 제공","es":"La habilidad de búsqueda de operaciones en GitHub proporciona capacidades de búsqueda avanzadas para código, problemas, solicitudes de extracción y más","fr":"La compétence de recherche d''opérations sur GitHub fournit des capacités de recherche avancées pour le code, les problèmes, les demandes d''extraction et plus encore","de":"Die Fähigkeit der GitHub-Suchoperationen bietet erweiterte Suchfunktionen für Code, Probleme, Pull-Requests und mehr","pt":"O skill de operações de busca do GitHub fornece capacidades de busca abrangentes, incluindo busca de código, problemas e repositórios","ru":"Навык операций поиска GitHub предоставляет всесторонние возможности поиска, включая поиск кода, проблем и репозиториев","ar":"المهارة عمليات البحث على جيت هاب توفر قدرات بحث شاملة، بما في ذلك البحث عن رمز، مشاكل ومستودعات","en":"my dotfiles"},"seo":{"title":{"zh":"GitHub 搜索操作技能","ja":"GitHub 検索操作スキル","ko":"GitHub 검색 연산 스킬","es":"Búsqueda de operaciones en GitHub","fr":"Recherche d''opérations sur GitHub","de":"GitHub-Suchoperationen","pt":"Operações de Busca no GitHub","ru":"Операции поиска на GitHub","ar":"عمليات البحث على جيت هاب","en":"search-operations"},"description":{"zh":"GitHub 搜索操作技能提供了全面的搜索功能，包括代码、问题、拉取请求、仓库和用户搜索","ja":"GitHub 検索操作スキルは、コード、問題、プルリクエスト、リポジトリ、ユーザーの包括的な検索機能を提供","ko":"GitHub 검색 연산 스킬은 