INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zjunlp/SkillNet/gh-cli', 'gh-cli', 'zjunlp', 'SkillNet', 'community', 'gh-cli zjunlp SkillNet community GitHub CLI（gh）是一个综合的命令行工具，用于与GitHub进行交互。它允许您创建、评估和连接AI技能 GitHub CLI（gh）は、GitHubとのコマンドライン操作を可能にする包括的なツールです。AIスキルの作成、評価、接続ができます GitHub CLI(gh)는 GitHub와 상호 작용하는 데 사용되는 포괄적인 명령줄 도구입니다. AI 스킬을 생성, 평가 및 연결할 수 있습니다 GitHub CLI es una herramienta de línea de comandos que permite a los desarrolladores interactuar con GitHub de manera eficiente. GitHub CLI est un outil de ligne de commande qui permet aux développeurs d''interagir avec GitHub de manière efficace. GitHub CLI ist ein Kommandozeilen-Tool, das es Entwicklern ermöglicht, mit GitHub effizient zu interagieren. O GH CLI é uma ferramenta de linha de comando para trabalhar com o GitHub. Aprenda a instalá-lo e usá-lo para aumentar a produtividade. GH CLI - это команда строки для работы с GitHub. Узнайте, как его установить и использовать для повышения производительности. GH CLI هو أداة سطر الأوامر للعمل مع جيت هاب. تعلم كيفية تثبيته واستخدامه لزيادة الإنتاجية. Create, Evaluate, and Connect AI Skills GitHub CLI AI技能 命令行工具 GitHub集成 创建AI技能 评估AI技能 连接AI技能 Create, Evaluate, and Connect AI Skills');
