INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lassestilvang/todo-gemini-3-pro-preview/gh-cli', 'gh-cli', 'lassestilvang', 'todo-gemini-3-pro-preview', 'community', 'gh-cli lassestilvang todo-gemini-3-pro-preview community GitHub CLI（gh）是GitHub的命令行工具，帮助开发者高效地管理仓库和协作 GitHub CLI（gh）は、GitHubのコマンドラインツールで、開発者がリポジトリとコラボレーションを効率的に管理できるようにします GitHub CLI（gh）は GitHub의 명령줄 도구로 개발자가 저장소와 협업을 효율적으로 관리하도록 도와줍니다 La CLI de GitHub (gh) es una herramienta para interactuar con GitHub desde la línea de comandos. Permite a los desarrolladores trabajar de manera eficiente. La CLI GitHub (gh) est un outil pour interagir avec GitHub depuis la ligne de commande. Elle permet aux développeurs de travailler de manière efficace. Die GitHub-CLI (gh) ist ein Tool, um mit GitHub über die Kommandozeile zu interagieren. Es ermöglicht Entwicklern, effizient zu arbeiten. O GitHub CLI é uma ferramenta de linha de comando que permite trabalhar com o GitHub de forma eficiente. Saiba como instalar e usar. GitHub CLI — это командная строка, которая позволяет работать с GitHub эффективно. Узнайте, как установить и использовать. GitHub CLI هي أداة سطر الأوامر التي تمكنك من العمل مع GitHub بفعالية. تعلم كيفية التثبيت والاستخدام. Gemini 3 Pro (Preview) GitHub CLI gh 命令行工具 开发效率 仓库管理 协作工具 Gemini 3 Pro (Preview)');
