INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ytqh/agent-skills/gh-cli', 'gh-cli', 'ytqh', 'agent-skills', 'community', 'gh-cli ytqh agent-skills community GitHub CLI（gh）是GitHub的命令行工具，允许开发者从命令行管理GitHub仓库和issue GitHub CLI（gh）は、GitHubのコマンドラインツールで、開発者がコマンドラインからGitHubリポジトリとissueを管理できるようにします GitHub CLI（gh）は GitHub의 명령줄 도구로 개발자가 명령줄에서 GitHub 저장소와 이슈를 관리할 수 있습니다 La CLI de GitHub es una herramienta para trabajar con GitHub desde la línea de comandos. Permite a los desarrolladores gestionar sus repositorios y colaborar con otros de manera eficiente La CLI GitHub est un outil pour travailler avec GitHub depuis la ligne de commande. Elle permet aux développeurs de gérer leurs dépôts et de collaborer avec d''autres de manière efficace Die GitHub-CLI ist ein Tool, um mit GitHub von der Kommandozeile aus zu arbeiten. Sie ermöglicht es Entwicklern, ihre Repositories zu verwalten und mit anderen effizient zusammenzuarbeiten O GitHub CLI é uma ferramenta de linha de comando que permite aos desenvolvedores trabalhar de forma eficiente com o GitHub. Veja como instalar e usar. GitHub CLI — это инструмент командной строки, который позволяет разработчикам эффективно работать с GitHub. Узнайте, как установить и использовать. GitHub CLI هي أداة سطر الأوامر تسمح للمطورين بالعمل بفعالية مع GitHub. تعرف على كيفية التثبيت والاستخدام. 常用开发模式的 skills GitHub CLI gh 命令行工具 GitHub API 自动化 仓库管理 issue管理 常用开发模式的 skills');
