INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hiroxtai/next-app-playground/gh-cli', 'gh-cli', 'hiroxtai', 'next-app-playground', 'community', 'gh-cli hiroxtai next-app-playground community GitHub CLI (gh) 是一个命令行工具，允许开发者从命令行与 GitHub 进行交互 GitHub CLI (gh) は、コマンドラインから GitHub と交互することを可能にするコマンドラインツールです GitHub CLI (gh) 는 명령줄에서 GitHub 와 상호 작용할 수 있는 명령줄 도구입니다 La CLI de GitHub permite trabajar de forma efectiva con GitHub desde la línea de comandos. Aprende a instalar y utilizar esta herramienta. La CLI GitHub permet de travailler efficacement avec GitHub depuis la ligne de commande. Découvrez comment l''installer et l''utiliser. Die GitHub-CLI ermöglicht eine effektive Arbeit mit GitHub von der Kommandozeile aus. Erfahren Sie, wie Sie diese Werkzeug installieren und verwenden. O gh-cli é uma ferramenta de linha de comando para trabalhar com o GitHub. Ele oferece uma forma eficaz de gerenciar repositórios e colaborar com outros desenvolvedores. gh-cli - это инструмент командной строки для работы с GitHub. Он предоставляет эффективный способ управления репозиториями и сотрудничества с другими разработчиками. غ-cli هو أداة سطر أوامر للعمل مع GitHub. وهو يقدم طريقة فعالة لإدارة المستودعات والتعاون مع المطورين الآخرين Next.js App Playground GitHub CLI gh 命令行工具 命令行与 GitHub 交互 GitHub API 自动化工作流 开发者工具 Next.js App Playground');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aiskillstore/marketplace/planning-with-files', 'community', 'aiskillstore', 'marketplace', 'aiskillstore/marketplace', 'planning-with-files', 0, 0, 70, '2026-02-20T04:13:19.574Z', '2026-02-20T04:34:50.734Z', 'daed3960d17c5bc0389f480de60319b3efe4b96d6591a40eddb8eb23af69f097', '{"id":"aiskillstore/marketplace/planning-with-files","name":"planning-with-files","description":{"zh":"文件规划技能是使用 Markdown 文件来管理和规划任务的方法，通过创建和更新文件来提高工作效率","ja":"ファイル計画スキルは、Markdown ファイルを使用してタスクを管理し計画する方法で、ファイルの作成と更新を通じて作業効率を向上させる","ko":"파일 계획 스킬은 Markdown 파일을 사용하여 태스크를 관리하고 계획하는 방법으로, 파일의 생성과 업데이트 통해 작업 효율을 향상시킵니다","es":"Planificación con archivos es una técnica para mejorar la productividad utilizando archivos markdown como memoria de trabajo","fr":"La planification avec fichiers est une technique pour améliorer la productivité en utilisant des fichiers markdown comme mémoire de travail","de":"Die Planung mit Dateien ist eine Technik, um die Produktivität zu verbessern, indem Markdown-Dateien als Arbeitsgedächtnis verwendet werden","pt":"O skill de planejamento com arquivos permite trabalhar com markdown para organizar tarefas complexas de forma eficaz","ru":"Навык планирования с файлами позволяет работать с markdown для организации сложных задач эффективно","ar":"مهارة التخطيط مع الملفات تمكن من العمل مع markdown لتخطيط المهام المعقدة بفعالية","en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"seo":{"title":{"zh":"文件规划技能","ja":"ファイル計画スキル","ko":"파일 계획 스킬","es":"Planificación con Archivos: Mejora la Productividad","fr":"Planification avec Fichiers: Améliorez la Productivité","de":"Planung mit Dateien: Erhöhen Sie die Produktivität","pt":"Planejamento com Arquivos: Otimização de Tarefas","ru":"Планирование с файлами: оптимизация задач","ar":"التخطيط مع الملفات: تحسين المهام","en":"planning-with-files"},"description":{"zh":"文件规划技能是使用 Markdown 文件来管理和规划任务的方法，通过创建和更新文件来提高工作效率","ja":"ファイル計画スキルは、Markdown ファイルを使用してタスクを管理し計画する方法で、ファイルの作成と更新を通じて作業効率を向上させる","ko":"파일 계획 스킬은 Markdown 파일을 사용하여 태스크를 관리하고 계획하는 방법으로, 파일의 생성과 업데이트 통해 작업 효율을 향상시킵니다","es":"Planificación con archivos es una técnica para mejorar la productividad utilizando archivos markdown como memoria de trabajo","fr":"La planification avec fichiers est une technique pour améliorer la productivité en utilisant des fichiers markdown comme mémoire de travail","de":"Die Planung mit Dateien ist eine Technik, um die Produktivität zu verbessern, indem Markdown-Dateien als Arbeitsgedächtnis verwendet werden","pt":"O skill de planejamento com arquivos permite trabalhar com markdown para organizar tarefas complexas de forma eficaz","ru":"Навык планирования с файлами позволяет работать с markdown для организации сложных задач эффективно","ar":"مهارة التخطيط مع الملفات تمكن من العمل مع markdown لتخطيط المهام المعقدة بفعالية","en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"definition":{"en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"features":{"zh":["使用 Markdown 文件作为工作记忆","创建任务计划文件","定义任务阶段","更新任务状态","使用三个文件模式管理任务"],"ja":["Markdown ファイルを工作記憶として使用","タスク計画ファイルの作成","タスク段階の定義","タスク状態の更新","三ファイルパターンを使用してタスクを管理"],"ko":["Markdown 파일을 작업記憶으로 사용","태스크 계획 파일 생성","태스크 단계 정의","태스크 상태 업데이트","세 개의 파일 패턴을 사용하여 태스크 관리"],"es":["Creación de archivos markdown para planificar tareas","Definición de fases con casillas de verificación","Actualización de archivos después de cada fase","Lectura de archivos antes de tomar decisiones","Uso de la técnica de los tres archivos para tareas no triviales"],"fr":["Création de fichiers markdown pour planifier des tâches","Définition de phases avec des cases à cocher","Mise à jour de fichiers après chaque phase","Lecture de fichiers avant de prendre des décisions","Utilisation de la technique des trois fichiers pour des tâches non triviales"],"de":["Erstellung von Markdown-Dateien zur Planung von Aufgaben","Definierung von Phasen mit Kontrollkästchen","Aktualisierung von Dateien nach jeder Phase","Lektüre von Dateien vor Entscheidungen","Verwendung der Dreidateitechnik für nicht-triviale Aufgaben"],"pt":["Crie arquivos markdown para planejar tarefas complexas","Defina fases com caixas de seleção","Atualize o status após cada fase","Leia antes de decidir para refreshar os objetivos","Use o padrão de três arquivos para organizar tarefas"],"ru":["Создайте файлы markdown для планирования сложных задач","Определите фазы с флажками","Обновите статус после каждой фазы","Прочитайте перед принятием решения для обновления целей","Используйте трехфайловый шаблон для организации задач"],"ar":["أنشئ ملفات markdown لتخطيط المهام المعقدة","حدد المراحل مع صناديق اختيار","حدّث الحالة بعد كل مرحلة","اقرأ قبل اتخاذ القرار لتحديث الأهداف","استخدم نمط الملفات الثلاث لتنظيم المهام"]},"keywords":{"zh":["文件规划","Markdown 文件","任务管理","工作效率","文件规划技能","任务规划","工作记忆","三个文件模式"],"ja":["ファイル計画","Markdown ファイル","タスク管理","作業効率","ファイル計画スキル","タスク計画","工作記憶","三ファイルパターン"],"ko":["파일 계획","Markdown 파일","태스크 관리","작업 효율","파일 계획 스킬","태스크 계획","작업記憶","세 개의 파일 패턴"],"es":["planificación con archivos","productividad","markdown","tareas complejas","gestión de proyectos","técnica de productividad","organización de tareas","gestión del tiempo"],"fr":["planification avec fichiers","productivité","markdown","tâches complexes","gestion de projets","technique de productivité","organisation de tâches","gestion du temps"],"de":["Planung mit Dateien","Produktivität","Markdown","komplexe Aufgaben","Projektmanagement","Produktivitätstechnik","Aufgabenorganisation","Zeitmanagement"],"pt":["planejamento de tarefas","arquivos markdown","gerenciamento de tarefas","produtividade","tarefas complexas","organização de tarefas","padrão de três arquivos"],"ru":["планирование задач","файлы markdown","управление задачами","производительность","сложные задачи","организация задач","трехфайловый шаблон"],"ar":["تخطيط المهام","ملفات markdown","إدارة المهام","الإنتاجية","المهام المعقدة","تنظيم المهام","نمط الملفات الثلاث"]}},"owner":"aiskillstore","repo":"marketplace","repoPath":"aiskillstore/marketplace","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.574Z","topics":[],"category":"community","skillMd":{"name":"planning-with-files","description":"Transforms workflow to use Manus-style persistent markdown files for planning, progress tracking, and knowledge storage. Use when starting complex tasks, multi-step projects, research tasks, or when the user mentions planning, organizing work, tracking progress, or wants structured output.","bodyPreview":"# Planning with Files\n\nWork like Manus: Use persistent markdown files as your \"working memory on disk.\"\n\n## Quick Start\n\nBefore ANY complex task:\n\n1. **Create `task_plan.md`** in the working directory\n2. **Define phases** with checkboxes\n3. **Update after each phase** - mark [x] and change status\n4. **Read before deciding** - refresh goals in attention window\n\n## The 3-File Pattern\n\nFor every non-trivial task, create THREE files:\n\n| File               | Purpose                     | When to Upda","body":"# Planning with Files\n\nWork like Manus: Use persistent markdown files as your \"working memory on disk.\"\n\n## Quick Start\n\nBefore ANY complex task:\n\n1. **Create `task_plan.md`** in the working directory\n2. **Define phases** with checkboxes\n3. **Update after each phase** - mark [x] and change status\n4. **Read before deciding** - refresh goals in attention window\n\n## The 3-File Pattern\n\nFor every non-trivial task, create THREE files:\n\n| File               | Purpose                     | When to Update   |\n| ------------------ | --------------------------- | ---------------- |\n| `task_plan.md`     | Track phases and progress   | After each phase |\n| `notes.md`         | Store findings and research | During research  |\n| `[deliverable].md` | Final output                | At completion    |\n\n## Core Workflow\n\n```\nLoop 1: Create task_plan.md with goal and phases\nLoop 2: Research → save to notes.md → update task_plan.md\nLoop 3: Read notes.md → create deliverable → update task_plan.md\nLoop 4: Deliver final output\n```\n\n### The Loop in Detail\n\n**Before each major action:**\n\n```bash\nRead task_plan.md  # Refresh goals in attention window\n```\n\n**After each phase:**\n\n```bash\nEdit task_plan.md  # Mark [x], update status\n```\n\n**When storing information:**\n\n```bash\nWrite notes.md     # Don''t stuff context, store in file\n```\n\n## task_plan.md Template\n\nCreate this file FIRST for any complex task:\n\n```markdown\n# Task Plan: [Brief Description]\n\n## Goal\n\n[One sentence describing the end state]\n\n## Phases\n\n- [ ] Phase 1: Plan and setup\n- [ ] Phase 2: Research/gather information\n- [ ] Phase 3: Execute/build\n- [ ] Phase 4: Review and deliver\n\n## Key Questions\n\n1. [Question to answer]\n2. [Question to answer]\n\n## Decisions Made\n\n- [Decision]: [Rationale]\n\n## Errors Encountered\n\n- [Error]: [Resolution]\n\n## Status\n\n**Currently in Phase X** - [What I''m doing now]\n```\n\n## notes.md Template\n\nFor research and findings:\n\n```markdown\n# Notes: [Topic]\n\n## Sources\n\n### Source 1: [Name]\n\n- URL: [link]\n- Key points:\n  - [Finding]\n  - [Finding]\n\n## Synthesized Findings\n\n### [Category]\n\n- [Finding]\n- [Finding]\n```\n\n## Critical Rules\n\n### 1. ALWAYS Create Plan First\n\nNever start a complex task without `task_plan.md`. This is non-negotiable.\n\n### 2. Read Before Decide\n\nBefore any major decision, read the plan file. This keeps goals in your attention window.\n\n### 3. Update After Act\n\nAfter completing any phase, immediately update the plan file:\n\n- Mark completed phases with [x]\n- Update the Status section\n- Log any errors encountered\n\n### 4. Store, Don''t Stuff\n\nLarge outputs go to files, not context. Keep only paths in working memory.\n\n### 5. Log All Errors\n\nEvery error goes in the \"Errors Encountered\" section. This builds knowledge for future tasks.\n\n## When to Use This Pattern\n\n**Use 3-file pattern for:**\n\n- Multi-step tasks (3+ steps)\n- Research tasks\n- Building/creating something\n- Tasks spanning multiple tool calls\n- Anything requiring organization\n\n**Skip for:**\n\n- Simple questions\n- Single-file edits\n- Quick lookups\n\n## Anti-Patterns to Avoid\n\n| Don''t                         | Do Instead                        |\n| ----------------------------- | --------------------------------- |\n| Use TodoWrite for persistence | Create `task_plan.md` file        |\n| State goals once and forget   | Re-read plan before each decision |\n| Hide errors and retry         | Log errors to plan file           |\n| Stuff everything in context   | Store large content in files      |\n| Start executing immediately   | Create plan file FIRST            |\n\n## Advanced Patterns\n\nSee [reference.md](reference.md) for:\n\n- Attention manipulation techniques\n- Error recovery patterns\n- Context optimization from Manus\n\nSee [examples.md](examples.md) for:\n\n- Real task examples\n- Complex workflow patterns\n"},"lastSynced":"2026-02-20T04:34:50.734Z","agentAnalysis":{"suitability":{"en":"Perfect for Productivity Agents needing structured task management with markdown files.","zh":"非常适合需要结构化任务管理和markdown文件的生产力代理。","ja":"構造化されたタスク管理とマークダウンファイルを必要とする生産性エージェントに最適です。","ko":"구조화된 태스크 관리와 마크다운 파일이 필요한 생산성 에이전트에 적합합니다.","es":"Perfecto para Agentes de Productividad que necesitan una gestión de tareas estructurada con archivos markdown.","fr":"Parfait pour les agents de productivité ayant besoin d''une gestion de tâches structurée avec des fichiers markdown.","de":"Perfekt für Produktivitätsagenten, die eine strukturierte Aufgabenverwaltung mit Markdown-Dateien benötigen.","pt":"Perfeito para Agentes de Produtividade que necessitam de gerenciamento de tarefas estruturado com arquivos markdown.","ru":"Идеально подходит для агентов продуктивности, которым требуется структурированное управление задачами с помощью файлов markdown.","ar":"مثالي للوكلاء الإنتاجيين الذين يحتاجون إلى إدارة مهام منظم مع الملفات المحددة بالتنسيق"},"recommendation":{"en":"Empowers agents to utilize the 3-file pattern, leveraging markdown files as working memory on disk, and streamlining task planning with phases and status updates using markdown checkboxes and files like `task_plan.md`.","zh":"赋予代理使用3文件模式的能力，利用markdown文件作为磁盘上的工作内存，并通过markdown复选框和文件（如`task_plan.md`）使用阶段和状态更新来简化任务规划。","ja":"エージェントが3ファイルパターンを利用できるようにし、マークダウンファイルをディスク上的ワーキングメモリとして利用し、`task_plan.md`などのファイルやマークダウンチェックボックスを使用してフェーズやステータス更新でタスク計画を簡素化します。","ko":"에이전트가 3개의 파일 패턴을 사용할 수 있도록 하며, 마크다운 파일을 디스크의 작업 메모리로서 활용하고, `task_plan.md`와 같은 파일이나 마크다운 체크박스를 사용하여 단계와 상태 업데이트로 태스크 계획을 간소화합니다.","es":"Permite a los agentes utilizar el patrón de 3 archivos, aprovechando los archivos markdown como memoria de trabajo en disco y simplificando la planificación de tareas con fases y actualizaciones de estado utilizando casillas de verificación markdown y archivos como `task_plan.md`.","fr":"Permet aux agents d''utiliser le modèle de 3 fichiers, en exploitant les fichiers markdown comme mémoire de travail sur disque et en rationalisant la planification des tâches avec des phases et des mises à jour de statut à l''aide de cases à cocher markdown et de fichiers comme `task_plan.md`.","de":"Ermöglicht es den Agenten, das 3-Datei-Muster zu verwenden, indem Markdown-Dateien als Arbeitsspeicher auf Datenträgern genutzt und die Aufgabenplanung mit Phasen und Statusaktualisierungen mithilfe von Markdown-Kontrollkästchen und Dateien wie `task_plan.md` optimiert wird.","pt":"Habilita os agentes a utilizarem o padrão de 3 arquivos, aproveitando arquivos markdown como memória de trabalho em disco e otimizando o planejamento de tarefas com fases e atualizações de status usando caixas de seleção markdown e arquivos como `task_plan.md`.","ru":"Позволяет агентам использовать трехфайловый шаблон, используя файлы markdown в качестве рабочей памяти на диске и оптимизируя планирование задач с помощью фаз и обновлений статуса с помощью флажков markdown и файлов типа `task_plan.md`.","ar":"يمكن للوكلاء استخدام نمط الملفات الثلاث، واستخدام الملفات المحددة بالتنسيق كذاكرة عمل على القرص، وتبسيط تخطيط المهام مع المراحل وتحديثات الحالة باستخدام مربعات تحديد التنسيق وملفات مثل `task_plan.md`."},"useCases":{"en":["Automating task planning with persistent markdown files","Generating and updating task phases with checkboxes","Debugging task progress using the 3-file pattern"],"zh":["使用持久化的markdown文件自动化任务规划","使用复选框生成和更新任务阶段","使用3文件模式调试任务进度"],"ja":["永続的なマークダウンファイルを使用してタスク計画を自動化する","チェックボックスを使用してタスクフェーズを生成および更新する","3ファイルパターンを使用してタスクの進捗をデバッグする"],"ko":["영속적인 마크다운 파일을 사용하여 태스크 계획을 자동화하는","체크박스를 사용하여 태스크 단계를 생성 및 업데이트하는","3개의 파일 패턴을 사용하여 태스크의 진행 상황을 디버깅하는"],"es":["Automatizar la planificación de tareas con archivos markdown persistentes","Generar y actualizar fases de tareas con casillas de verificación","Depurar el progreso de las tareas utilizando el patrón de 3 archivos"],"fr":["Automatiser la planification des tâches avec des fichiers markdown persistants","Générer et mettre à jour les phases de tâches avec des cases à cocher","Déboguer la progression des tâches en utilisant le modèle de 3 fichiers"],"de":["Automatisieren der Aufgabenplanung mit persistenten Markdown-Dateien","Erstellen und Aktualisieren von Aufgabenphasen mit Kontrollkästchen","Debuggen des Aufgabenfortschritts unter Verwendung des 3-Datei-Musters"],"pt":["Automatizar o planejamento de tarefas com arquivos markdown persistentes","Gerar e atualizar fases de tarefas com caixas de seleção","Depurar o progresso da tarefa usando o padrão de 3 arquivos"],"ru":["Автоматизировать планирование задач с помощью постоянных файлов markdown","Генерировать и обновлять фазы задач с помощью флажков","Отлаживать прогресс задачи с помощью трехфайлового шаблона"],"ar":["تأتمتة تخطيط المهام مع الملفات المحددة بالتنسيق الثابتة","توليد وتحديث مراحل المهام مع مربعات التحديد","تصحيح أخطاء تقدم المهمة باستخدام نمط الملفات الثلاث"]},"limitations":{"en":["Requires filesystem access to create and update markdown files","Limited to agents compatible with security-audited skills for Claude, Codex & Claude Code"],"zh":["需要文件系统访问权限来创建和更新markdown文件","仅限与Claude、Codex和Claude Code兼容的安全审计技能的代理"],"ja":["マークダウンファイルを作成および更新するためにファイルシステムへのアクセスが必要","Claude、CodexおよびClaude Codeと互換性のあるセキュリティ監査スキルのエージェントに限定"],"ko":["마크다운 파일을 생성 및 업데이트하기 위해 파일 시스템 접근 권한이 필요","클라우드, 코덱스 및 클라우드 코드와 호환되는 보안 감사 스킬의 에이전트로 제한"],"es":["Requiere acceso al sistema de archivos para crear y actualizar archivos markdown","Limitado a agentes compatibles con habilidades auditadas de seguridad para Claude, Codex y Claude Code"],"fr":["Nécessite un accès au système de fichiers pour créer et mettre à jour des fichiers markdown","Limité aux agents compatibles avec des compétences auditées en matière de sécurité pour Claude, Codex et Claude Code"],"de":["Benötigt Zugriff auf das Dateisystem, um Markdown-Dateien zu erstellen und zu aktualisieren","Begrenzt auf Agenten, die mit sicherheitsgeprüften Fähigkeiten für Claude, Codex und Claude Code kompatibel sind"],"pt":["Requer acesso ao sistema de arquivos para criar e atualizar arquivos markdown","Limitado a agentes compatíveis com habilidades auditadas de segurança para Claude, Codex e Claude Code"],"ru":["Требует доступа к файловой системе для создания и обновления файлов markdown","Ограничен агентами, совместимыми с навыками, проверенными на безопасность для Claude, Codex и Claude Code"],"ar":["يتطلب الوصول إلى نظام الملفات لإنشاء وتحديث الملفات المحددة بالتنسيق","محدود بالوكلاء المتوافقة مع المهارات المأمونة للأمان ل كلود، كودكس وكلود كود"]},"version":3},"contentHash":"daed3960d17c5bc0389f480de60319b3efe4b96d6591a40eddb8eb23af69f097","qualityScore":70}');
