INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aiskillstore/marketplace/planning-with-files', 'planning-with-files', 'aiskillstore', 'marketplace', 'community', 'planning-with-files aiskillstore marketplace community 文件规划技能是使用 Markdown 文件来管理和规划任务的方法，通过创建和更新文件来提高工作效率 ファイル計画スキルは、Markdown ファイルを使用してタスクを管理し計画する方法で、ファイルの作成と更新を通じて作業効率を向上させる 파일 계획 스킬은 Markdown 파일을 사용하여 태스크를 관리하고 계획하는 방법으로, 파일의 생성과 업데이트 통해 작업 효율을 향상시킵니다 Planificación con archivos es una técnica para mejorar la productividad utilizando archivos markdown como memoria de trabajo La planification avec fichiers est une technique pour améliorer la productivité en utilisant des fichiers markdown comme mémoire de travail Die Planung mit Dateien ist eine Technik, um die Produktivität zu verbessern, indem Markdown-Dateien als Arbeitsgedächtnis verwendet werden O skill de planejamento com arquivos permite trabalhar com markdown para organizar tarefas complexas de forma eficaz Навык планирования с файлами позволяет работать с markdown для организации сложных задач эффективно مهارة التخطيط مع الملفات تمكن من العمل مع markdown لتخطيط المهام المعقدة بفعالية Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified. 文件规划 Markdown 文件 任务管理 工作效率 文件规划技能 任务规划 工作记忆 三个文件模式 Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified.');
