INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Jeffallan/claude-skills/wordpress-pro', 'wordpress-pro', 'Jeffallan', 'claude-skills', 'community', 'wordpress-pro Jeffallan claude-skills community WordPress Pro 是一个专注于高级 WordPress 开发的技能，包括自定义主题、插件、Gutenberg 块、WooCommerce 和性能优化 WordPress Pro は、高度な WordPress 開発に特化したスキルで、カスタムテーマ、プラグイン、Gutenberg ブロック、WooCommerce、パフォーマンス最適化が含まれます 워드프레스 프로는 고급 워드프레스 개발에 중점을 둔 스킬로 커스텀 테마, 플러그인, 거트버그 블록, 우커머스, 성능 최적화를 포함합니다 Desarrollador WordPress Pro con experiencia en temas personalizados, plugins y optimización de rendimiento Développeur WordPress Pro avec une expérience dans les thèmes personnalisés, les plugins et l''optimisation des performances WordPress Pro-Entwickler mit Erfahrung in maßgeschneiderten Themes, Plugins und Leistungsoptimierung O desenvolvedor WordPress Pro é um especialista em soluções personalizadas para WordPress, com foco em temas, plugins e otimização de desempenho Профессиональный разработчик WordPress - это специалист по кастомным решениям для WordPress, с фокусом на темах, плагинах и оптимизации производительности مطور ووردبريس المحترف هو خبير في الحلول المخصصة لوردبريس، مع تركيز على التصاميم والملحقات وتحسين الأداء 66 Specialized Skills for Full-Stack Developers. Transform Claude Code into your expert pair programmer. WordPress 开发 全栈开发 自定义主题 插件开发 Gutenberg 块 WooCommerce 性能优化 66 Specialized Skills for Full-Stack Developers. Transform Claude Code into your expert pair programmer.');
