INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jeremylongshore/claude-code-plugins-plus-skills/swagger-doc-creator', 'swagger-doc-creator', 'jeremylongshore', 'claude-code-plugins-plus-skills', 'community', 'swagger-doc-creator jeremylongshore claude-code-plugins-plus-skills community Swagger API Swagger API Swagger API El creador de documentación Swagger es una habilidad que proporciona asistencia automatizada para tareas de creación de documentación de API. Le créateur de documentation Swagger est une compétence qui fournit une assistance automatisée pour les tâches de création de documentation d''API. Der Swagger-Dokumentationsersteller ist eine Fähigkeit, die automatisierte Unterstützung für die Erstellung von API-Dokumentationen bietet. O Criador de Documentação Swagger fornece assistência automatizada para tarefas de criação de documentação Swagger no domínio de Desenvolvimento de API. Создатель докуметации Swagger предоставляет автоматизированную помощь для задач создания докуметации Swagger в области разработки API. مُنشئ وثائق Swagger يوفر مساعدة آلية لإنجاز مهام إنشاء وثائق Swagger في مجال تطوير واجهات برمجة التطبيقات. 270+ Claude Code plugins with 739 agent skills. Production orchestration patterns, interactive tutorials (11 Jupyter notebooks), and CCPI package manager. 4.13.0 Swagger API API REST API GraphQL API OpenAPI API Swagger 270+ Claude Code plugins with 739 agent skills. Production orchestration patterns, interactive tutorials (11 Jupyter notebooks), and CCPI package manager. 4.13.0');
