INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jeremylongshore/claude-code-plugins-plus-skills/github-actions-starter', 'github-actions-starter', 'jeremylongshore', 'claude-code-plugins-plus-skills', 'community', 'github-actions-starter jeremylongshore claude-code-plugins-plus-skills community 该技能提供自动化的GitHub Actions入门任务帮助，涵盖版本控制、容器化、CI/CD和基础设施等DevOps基础知识 このスキルは、GitHub Actionsスターター タスクの自動化を提供し、DevOpsの基礎知識をカバーします 이 스킬은 GitHub Actions 시작하기 작업 자동화를 제공하며, DevOps 기초 지식을 다룹니다 Github Actions Starter proporciona asistencia automatizada para tareas de inicio de acciones de Github Github Actions Starter fournit une assistance automatisée pour les tâches de démarrage des actions Github Github Actions Starter bietet automatisierte Unterstützung für Aufgaben zum Starten von Github-Aktionen O iniciador de ações do GitHub fornece assistência automatizada para tarefas de ações do GitHub dentro do domínio DevOps Basics. Стартер действий GitHub предоставляет автоматизированную помощь для задач действий GitHub в области DevOps Basics. مبتدئ إجراءات جيثب يوفر مساعدة آلية للمهام إجراءات جيثب داخل مجال أساسيات ديفوبس. 270+ Claude Code plugins with 739 agent skills. Production orchestration patterns, interactive tutorials (11 Jupyter notebooks), and CCPI package manager. 4.13.0 GitHub Actions DevOps 自动化 版本控制 容器化 CI/CD 基础设施 270+ Claude Code plugins with 739 agent skills. Production orchestration patterns, interactive tutorials (11 Jupyter notebooks), and CCPI package manager. 4.13.0');
