INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jeremylongshore/claude-code-plugins-plus-skills/rest-endpoint-designer', 'rest-endpoint-designer', 'jeremylongshore', 'claude-code-plugins-plus-skills', 'community', 'rest-endpoint-designer jeremylongshore claude-code-plugins-plus-skills community REST Endpoint Designer 是一个提供自动化 REST API 设计任务的技能，涵盖 API 开发、REST、GraphQL、OpenAPI 等 REST エンドポイント デザイナーは、REST API の設計タスクを自動化するスキルで、API 開発、REST、GraphQL、OpenAPI などをカバー REST 엔드포인트 디자이너는 REST API 디자인 작업을 자동화하는 스킬로, API 개발, REST, GraphQL, OpenAPI 등을 포함 El skill de diseño de puntos de terminación de REST proporciona asistencia automatizada para tareas de diseño de puntos de terminación de REST dentro del dominio de desarrollo de API La compétence de conception de points de terminaison REST fournit une assistance automatisée pour les tâches de conception de points de terminaison REST dans le domaine du développement d''API Der REST-Endpunktdesign-Skill bietet automatisierte Unterstützung für REST-Endpunktdesign-Aufgaben im API-Entwicklungsbereich O skill de designer de endpoint de REST fornece assistência automatizada para tarefas de designer de endpoint de REST no domínio de desenvolvimento de API. Навык дизайнера REST-эндоинтов обеспечивает автоматизированную помощь в задачах дизайнера REST-эндоинтов в области разработки API. مهارة مصمم نهاية نقطة REST توفر مساعدة آلية لإدارة مهام تصميم نقطة النهاية REST في مجال تطوير API. 270+ Claude Code plugins with 739 agent skills. Production orchestration patterns, interactive tutorials (11 Jupyter notebooks), and CCPI package manager. 4.13.0 REST API 设计 API 开发 REST GraphQL OpenAPI 自动化设计 最佳实践 设计模式 270+ Claude Code plugins with 739 agent skills. Production orchestration patterns, interactive tutorials (11 Jupyter notebooks), and CCPI package manager. 4.13.0');
