INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('edyhvh/shafan/gh-cli', 'community', 'edyhvh', 'shafan', 'edyhvh/shafan', 'gh-cli', 0, 0, 70, '2026-02-20T04:13:19.572Z', '2026-03-01T07:17:40.847Z', 'd38f7093e4d5afa4e0cc17fa7b0bf7b85bfe86b71f47ffc8d53e598391f68809', '{"id":"edyhvh/shafan/gh-cli","name":"gh-cli","description":{"zh":"GitHub CLI AIエージェント是一种命令行工具，用于执行GitHub操作。它支持仓库、问题、拉取请求、Actions、项目、发布、代码片段、代码空间、组织、扩展等功能","ja":"GitHub CLI AIエージェントは、コマンドラインからGitHubを操作するためのツールです。レポジトリ、イシュー、プルリクエスト、Actions、プロジェクト、リリース、ギスト、コードスペース、組織、拡張機能などをサポートします","ko":"GitHub CLI AI 에이전트는 명령행에서 GitHub를 연산하는 툴입니다. 저장소, 이슈, 풀 리퀘스트, Actions, 프로젝트, 릴리즈, 깃 코드, 코드스페이스, 조직, 확장 기능 등을 지원합니다","es":"La CLI de GitHub (gh) es una herramienta de línea de comandos para gestionar repositorios, problemas, solicitudes de extracción y más","fr":"La CLI GitHub (gh) est un outil de ligne de commande pour gérer des dépôts, des problèmes, des demandes d''extraction et plus","de":"Die GitHub-CLI (gh) ist ein Kommandozeilen-Tool zum Verwalten von Repositorys, Problemen, Pull-Anfragen und mehr","pt":"O gh-cli é uma ferramenta de linha de comando para gerenciar operações do GitHub. Ele permite automatizar tarefas e melhorar a produtividade","ru":"ИИ Агент gh-cli - это командная строка для управления операциями GitHub. Он позволяет автоматизировать задачи и повысить производительность","ar":"أداة الذكاء الاصطناعي gh-cli هي واجهة سطر الأوامر لإدارة عمليات GitHub. أنها تسمح بالتخصيص وتحسين الإنتاجية","en":"GitHub CLI (gh) comprehensive reference for repositories, issues, pull requests, Actions, projects, releases, gists, codespaces, organizations, extensions, and all GitHub operations from the command line."},"seo":{"title":{"zh":"GitHub CLI AIエージェント - 命令行GitHub操作","ja":"GitHub CLI AIエージェント - コマンドラインからGitHubを操作","ko":"GitHub CLI AI 에이전트 - 명령행에서 GitHub 연산","es":"Herramientas de AI: gh-cli para GitHub","fr":"Outils IA: gh-cli pour GitHub","de":"KI-Tools: gh-cli für GitHub","pt":"Ferramentas de IA: gh-cli - GitHub CLI","ru":"ИИ Агенты: gh-cli - Командная строка GitHub","ar":"أدوات الذكاء الاصطناعي: gh-cli - واجهة سطر الأوامر GitHub","en":"gh-cli"},"description":{"zh":"GitHub CLI AIエージェント是一种命令行工具，用于执行GitHub操作。它支持仓库、问题、拉取请求、Actions、项目、发布、代码片段、代码空间、组织、扩展等功能","ja":"GitHub CLI AIエージェントは、コマンドラインからGitHubを操作するためのツールです。レポジトリ、イシュー、プルリクエスト、Actions、プロジェクト、リリース、ギスト、コードスペース、組織、拡張機能などをサポートします","ko":"GitHub CLI AI 에이전트는 명령행에서 GitHub를 연산하는 툴입니다. 저장소, 이슈, 풀 리퀘스트, Actions, 프로젝트, 릴리즈, 깃 코드, 코드스페이스, 조직, 확장 기능 등을 지원합니다","es":"La CLI de GitHub (gh) es una herramienta de línea de comandos para gestionar repositorios, problemas, solicitudes de extracción y más","fr":"La CLI GitHub (gh) est un outil de ligne de commande pour gérer des dépôts, des problèmes, des demandes d''extraction et plus","de":"Die GitHub-CLI (gh) ist ein Kommandozeilen-Tool zum Verwalten von Repositorys, Problemen, Pull-Anfragen und mehr","pt":"O gh-cli é uma ferramenta de linha de comando para gerenciar operações do GitHub. Ele permite automatizar tarefas e melhorar a produtividade","ru":"ИИ Агент gh-cli - это командная строка для управления операциями GitHub. Он позволяет автоматизировать задачи и повысить производительность","ar":"أداة الذكاء الاصطناعي gh-cli هي واجهة سطر الأوامر لإدارة عمليات GitHub. أنها تسمح بالتخصيص وتحسين الإنتاجية","en":"GitHub CLI (gh) comprehensive reference for repositories, issues, pull requests, Actions, projects, releases, gists, codespaces, organizations, extensions, a..."},"definition":{"en":"GitHub CLI (gh) comprehensive reference for repositories, issues, pull requests, Actions, projects, releases, gists, codespaces, organizations, extensions, and all GitHub operations from the command line."},"features":{"zh":["支持仓库、问题、拉取请求、Actions等功能","命令行从GitHub执行操作","支持代码片段、代码空间、组织、扩展功能","提高开发效率","简单易用"],"ja":["レポジトリ、イシュー、プルリクエスト、Actionsなどをサポート","コマンドラインからGitHubを操作","ギスト、コードスペース、組織、拡張機能をサポート","開発効率を向