INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('edyhvh/shafan/gh-cli', 'gh-cli', 'edyhvh', 'shafan', 'community', 'gh-cli edyhvh shafan community GitHub CLI AIエージェント是一种命令行工具，用于执行GitHub操作。它支持仓库、问题、拉取请求、Actions、项目、发布、代码片段、代码空间、组织、扩展等功能 GitHub CLI AIエージェントは、コマンドラインからGitHubを操作するためのツールです。レポジトリ、イシュー、プルリクエスト、Actions、プロジェクト、リリース、ギスト、コードスペース、組織、拡張機能などをサポートします GitHub CLI AI 에이전트는 명령행에서 GitHub를 연산하는 툴입니다. 저장소, 이슈, 풀 리퀘스트, Actions, 프로젝트, 릴리즈, 깃 코드, 코드스페이스, 조직, 확장 기능 등을 지원합니다 La CLI de GitHub (gh) es una herramienta de línea de comandos para gestionar repositorios, problemas, solicitudes de extracción y más La CLI GitHub (gh) est un outil de ligne de commande pour gérer des dépôts, des problèmes, des demandes d''extraction et plus Die GitHub-CLI (gh) ist ein Kommandozeilen-Tool zum Verwalten von Repositorys, Problemen, Pull-Anfragen und mehr O gh-cli é uma ferramenta de linha de comando para gerenciar operações do GitHub. Ele permite automatizar tarefas e melhorar a produtividade ИИ Агент gh-cli - это командная строка для управления операциями GitHub. Он позволяет автоматизировать задачи и повысить производительность أداة الذكاء الاصطناعي gh-cli هي واجهة سطر الأوامر لإدارة عمليات GitHub. أنها تسمح بالتخصيص وتحسين الإنتاجية GitHub CLI (gh) comprehensive reference for repositories, issues, pull requests, Actions, projects, releases, gists, codespaces, organizations, extensions, and all GitHub operations from the command line. GitHub CLI AIエージェント 命令行GitHub操作 GitHub操作工具 开发效率提升 GitHub CLI 教程 GitHub CLI 安装 GitHub CLI 使用方法 GitHub CLI替代品 GitHub CLI vs Git GitHub CLI (gh) comprehensive reference for repositories, issues, pull requests, Actions, projects, releases, gists, codespaces, organizations, extensions, and all GitHub operations from the command line.');
